const inputItems = $input.all();
const MAX_JOBS_TO_SCORE = 20;
const RESUME_MAX_CHARS = 8000;

function decodeHtml(html) {
  return String(html || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function prepareUser(user) {
  const resume = String(user.resume_text || '');
  return {
    ...user,
    resume_text: resume.length <= RESUME_MAX_CHARS
      ? resume
      : resume.slice(0, RESUME_MAX_CHARS).trimEnd() + '\n…[truncated]',
  };
}

function extractJobs(itemJson) {
  if (Array.isArray(itemJson.jobs)) return itemJson.jobs;
  if (itemJson.title || itemJson.job_title) return [itemJson];
  return [];
}

function matchesKeywords(job, keywords) {
  const title = String(job.title || job.job_title || '').toLowerCase();
  const description = decodeHtml(job.content || job.description || '').toLowerCase();
  const company = String(job.company_name || job.company || '').toLowerCase();
  const text = `${title} ${description} ${company}`;
  if (!keywords.length) return true;
  return keywords.some((keyword) => text.includes(keyword));
}

// Group API responses by user so each preference set is applied correctly
const byUser = new Map();
for (const item of inputItems) {
  const rawUser = item.json._user;
  if (!rawUser || !rawUser.user_id) {
    throw new Error('Missing _user on merged job list item — Tag User nodes must run before Merge');
  }
  const key = String(rawUser.user_id);
  if (!byUser.has(key)) {
    byUser.set(key, { user: prepareUser(rawUser), jobs: [] });
  }
  byUser.get(key).jobs.push(...extractJobs(item.json));
}

const output = [];
for (const { user, jobs } of byUser.values()) {
  const keywords = [
    ...(user.target_keywords || []),
    ...(user.target_roles || []),
  ].map((k) => String(k).toLowerCase().trim()).filter(Boolean);

  const filtered = jobs.filter((job) => matchesKeywords(job, keywords));

  for (const job of filtered.slice(0, MAX_JOBS_TO_SCORE)) {
    const fullText = decodeHtml(job.content || job.description || '');
    output.push({
      json: {
        ...job,
        _job_text: fullText.slice(0, 50000),
        content: fullText.slice(0, 3000),
        description: decodeHtml(job.description || '').slice(0, 3000),
        _user: user,
      },
    });
  }
}

return output;

